const programsNav=document.createElement('button');programsNav.dataset.view='programs';programsNav.textContent='◈  Programs & company';document.querySelector('nav').append(programsNav);
const programsPanel=document.createElement('section');programsPanel.id='programs-panel';programsPanel.className='programs-panel';programsPanel.hidden=true;document.querySelector('.panel').after(programsPanel);
function renderPrograms(){const c=COMPANY_REFERENCE;programsPanel.innerHTML=`<div class="company-summary"><span class="eyebrow">COMPANY REFERENCE</span><h2>Care built around youth and families.</h2><p>${esc(c.purpose)}</p><div class="reference-note">Company details are based on the supplied Eero company document, flyers, and call card. Review draft content before using it operationally.</div><div class="company-grid"><div><h3>Mission</h3><p>${esc(c.mission)}</p></div><div><h3>Vision</h3><p>${esc(c.vision)}</p><h3>Background in the materials</h3><p>Founded in ${esc(c.founded)} by ${esc(c.founder)} to serve ${esc(c.region)}. ${esc(c.meaning)}</p></div><div><h3>Contact</h3><p>${esc(c.contact.phone)}<br>${esc(c.contact.email)}<br>${esc(c.contact.address)}</p><h3>Service approach</h3><p>${esc(c.approach)}</p></div><div><h3>Services described</h3><ul>${c.services.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div></div></div><div class="program-title"><h2>Group program directory</h2><p>Six programs from your company document. Enrollment records use fictional case labels.</p></div><div class="program-grid">${c.programs.map(p=>`<article class="program-card"><span class="eyebrow">${esc(p.kind)}</span><h3>${esc(p.name)}</h3><span class="age-tag">${esc(p.ages)}</span><p>${esc(p.summary)}</p><details><summary>Program focus</summary><ul>${p.focus.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></details><button class="secondary" data-enroll="${esc(p.id)}">＋ Enroll sample case</button><div class="enrollment-list">${(state.enrollments||[]).filter(e=>e.programId===p.id).map(e=>`<div>${esc(state.cases.find(c=>c.id===e.caseId)?.label||'Case removed')} <button data-unenroll="${esc(e.id)}" aria-label="Remove sample enrollment">×</button></div>`).join('')}</div></article>`).join('')}</div>`}
const baseRender=render;render=function(){const showing=currentView==='programs';if(showing){currentView='overview';baseRender();currentView='programs';$('page-title').textContent='Programs & company';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view==='programs'))}else baseRender();document.querySelector('.panel').hidden=showing;programsPanel.hidden=!showing;if(showing)renderPrograms()};
programsNav.onclick=()=>{currentView='programs';render()};
const enrollmentDialog=document.createElement('dialog');enrollmentDialog.id='enrollment-modal';enrollmentDialog.innerHTML='<form id="enrollment-form"><div class="modal-heading"><h2 id="enrollment-title">Enroll sample case</h2><button type="button" class="close" aria-label="Close">×</button></div><p class="muted">This records a sample program assignment. It does not determine clinical eligibility or authorize care.</p><label class="field">Case folder<select id="enrollment-case" required></select></label><div class="modal-actions"><button class="primary" type="submit">Save enrollment</button></div></form>';document.body.append(enrollmentDialog);enrollmentDialog.querySelector('.close').onclick=()=>enrollmentDialog.close();let chosenProgram;
programsPanel.onclick=async e=>{const add=e.target.closest('[data-enroll]'),remove=e.target.closest('[data-unenroll]');if(add){chosenProgram=add.dataset.enroll;$('enrollment-title').textContent=COMPANY_REFERENCE.programs.find(p=>p.id===chosenProgram).name;$('enrollment-case').innerHTML=caseOptions();enrollmentDialog.showModal()}if(remove){state.enrollments=(state.enrollments||[]).filter(x=>x.id!==remove.dataset.unenroll);await persist();toast('Sample enrollment removed.')}};
$('enrollment-form').onsubmit=async e=>{e.preventDefault();state.enrollments??=[];const caseId=$('enrollment-case').value;if(state.enrollments.some(x=>x.caseId===caseId&&x.programId===chosenProgram)){toast('This sample case is already enrolled.');return}state.enrollments.push({id:uid(),programId:chosenProgram,caseId,createdAt:new Date().toISOString()});await persist();enrollmentDialog.close();toast('Sample enrollment saved.')};
for(const id of ['service-filter','case-service']){const option=document.createElement('option');option.textContent='Parent Coaching';$(id).append(option)}
